/* ##### CHAPTER SCREEN 7 · Menus and encyclopedia #####
   File: src/js/ui/07-menus-encyclopedia.js
   What it does: Home screen, Skirmish setup, Campaign and Battles lists, mission briefings, Encyclopedia text,
   Settings.
   Things you can tweak:
     - BUILD: the version shown in Settings.
     - ENCY_UNITS / ENCY_BLDS / ENCY_CIVS / ENCY_GUIDE: encyclopedia text.
     - CAMPAIGNS / MISSIONS: mission lists, briefings and which are unlocked.
   ############################################################################ */
/* ---------------- main menu ---------------- */
// links to the demos: relative on the live site, absolute anywhere else (the playable artifact)
const SITE = /github\.io$/.test(location.hostname) ? './' : 'https://therediris0827.github.io/SEA-RTS/';
let mapChoice = 'same', mapKind = 'strait', pciv = 0, pfoe = 1, encyTab = 'heroes', startAge = 1;
let encyCiv = 'all';   // Encyclopedia civ filter (Iylia, 2026-11-10)
const MAP_NOTES = { strait: 'Sea along the south, a bay between the bases.', river: 'Rivers cut the land. Sandy fords are the only dry crossings.', islands: 'An island each. Every attack needs galleys to land troops.' };
// show a menu screen
function showMenu(name) {
  $('menu').hidden = !name;
  for (const n of ['home', 'skirmish', 'campaign', 'brief', 'battles', 'ency', 'settings', 'load']) $('m-' + n).hidden = n !== name;
  $('menu').scrollTop = 0;
  if (name === 'home') refreshHome();
  if (name === 'skirmish') syncMenuSegs();
  if (name === 'settings') { syncMenuSegs(); setVerNote(); const n = slotMetas().filter(Boolean).length; $('m-savenote').textContent = n ? n + ' of 3 save slots in use. Load game lists them.' : 'No game saved. Games save by themselves while you play.'; }
  if (name === 'load') renderSlots();
  if (name === 'ency') renderEncy();
  if (name) $('menu').scrollTop = 0;
}
const BUILD = '0.9.53 \u00b7 14 Nov 2026';
/* deleting the saved game takes two taps: the first turns the button red and asks */
let delT = 0;
// two-tap Delete on the home screen
function delAsk(on) {
  const b = $('m-del'); if (!b) return;
  clearTimeout(delT); b.classList.toggle('ask', on); b.querySelector('small').textContent = on ? 'Sure?' : 'Delete';
  if (on) delT = setTimeout(() => delAsk(false), 4000);
}
// update the home screen
function refreshHome() {
  const i = slotNewest(), m = slotMetas()[i], n = slotMetas().filter(Boolean).length;
  $('m-ver').textContent = 'v' + BUILD + (navigator.onLine === false ? ' \u00b7 offline' : '');
  $('m-controw').hidden = !m; delAsk(false);
  if (m) $('m-cont-sub').textContent = m.title + ' \u00b7 ' + slotLine(m);
  $('m-load-sub').textContent = n ? n + ' of 3 saved' : 'No saves yet';
}
const TRASH = '<svg width="20" height="24" viewBox="0 0 10 12" shape-rendering="crispEdges" aria-hidden="true"><path d="M0 2h10v1h-10zM3 0h4v2h-4zM1 3h8v9h-8z" fill="currentColor"></path><path d="M3 5h1v5h-1zM6 5h1v5h-1z" fill="var(--face)"></path></svg>';
// Load game screen
function renderSlots() {
  const m = slotMetas();
  $('m-slots').innerHTML = m.map((x, i) => x
    ? '<div class="m-controw"><button class="px px-p m-cont m-slot-b" data-m="loadslot" data-v="' + i + '"><span><b>' + (i + 1) + '. ' + x.title + '</b><small>' + slotLine(x) + '</small></span></button>'
      + '<button class="px m-del" data-m="delslot" data-v="' + i + '" aria-label="Delete this save">' + TRASH + '<small>Delete</small></button></div>'
    : '<p class="px m-slot-empty">' + (i + 1) + '. Empty slot</p>').join('');
}
/* version, updates and exit (the installed app has no browser bar to reload or close it) */
function setVerNote(t) { const e = $('m-vernote'); if (e) e.textContent = t || 'You have version ' + BUILD + '.'; }
// Settings > Check for updates
function checkForUpdate() {
  saveGame();
  const reg = window.swReg;
  if (!reg) { setVerNote('Checking\u2026'); location.reload(); return; }
  setVerNote('Checking for a new version\u2026');
  reg.update().then(() => {
    const nw = reg.installing || reg.waiting;
    if (!nw) { setVerNote('You have the latest version (' + BUILD + ').'); return; }
    setVerNote('Downloading the new version\u2026');
    const done = () => { if (nw.state === 'activated') location.reload(); };
    nw.addEventListener('statechange', done); done();
  }).catch(() => setVerNote('No connection. Try again when you are online.'));
}
// bar saying a new version is ready
function showUpdateReady() {
  if ($('upd-bar')) return;
  const b = document.createElement('button'); b.id = 'upd-bar'; b.className = 'upd-bar';
  b.textContent = 'A new version is ready. Tap to update.';
  b.addEventListener('click', () => { saveGame(); location.reload(); });
  document.body.appendChild(b);
}
// Exit button
function exitApp() {
  saveGame();
  try { window.close(); } catch (e) { /* not allowed here */ }
  setTimeout(() => { const b = document.querySelector('.m-exit'); if (b) { b.classList.add('m-exit-hint'); b.setAttribute('aria-label', 'Swipe the app away to close it'); } toastMenu('Your game is saved. Swipe the app away to close it.'); }, 300);
}
// pop-up message on the menu
function toastMenu(t) {
  let e = $('m-toast'); if (!e) { e = document.createElement('div'); e.id = 'm-toast'; e.className = 'upd-bar'; e.style.pointerEvents = 'none'; document.body.appendChild(e); }
  e.textContent = t; e.hidden = false; clearTimeout(e._t); e._t = setTimeout(() => { e.hidden = true; }, 3000);
}
// highlight the chosen Skirmish options
function syncMenuSegs() {
  const press = (box, attr, val) => document.querySelectorAll('#' + box + ' button').forEach((b) => b.setAttribute('aria-pressed', b.dataset[attr] === String(val) ? 'true' : 'false'));
  press('m-diff', 'v', diff); press('m-sage', 'v', startAge); press('m-map', 'v', mapChoice); press('m-mapk', 'v', mapKind); if ($('m-mapnote')) $('m-mapnote').textContent = MAP_NOTES[mapKind]; press('m-speed', 'v', settings.speed); press('m-bars', 'v', settings.bars); press('m-sound', 'v', settings.sound); press('m-music', 'v', settings.music);
  let tap = 'single'; try { if (localStorage.getItem('seak-tapmode') === 'double') tap = 'double'; } catch (_) { /* ignore */ } press('m-tap', 'v', tap);
  document.querySelectorAll('#m-civpick [data-m="civ"]').forEach((b) => { const on = +b.dataset.v === pciv; b.classList.toggle('sel', on); b.setAttribute('aria-current', on ? 'true' : 'false'); });
  press('m-foe', 'v', pfoe); document.querySelectorAll('#m-foe button').forEach((b) => { b.disabled = +b.dataset.v === pciv; });
}
